 if(r.phase===2){const t=r.target,old=t?(t.branch?D.bases[r.sequence[t.index]].pair:r.sequence[t.index]):null;h+='<p>Complete a nova fita, seguindo a seta 5′ → 3′. Trabalhamos uma fita por vez para dar clareza ao processo.</p><div class="info-card"><p>'+(t?'Molécula '+(t.branch+1)+' · posição '+(t.index+1)+'<br>Base do molde: <b>'+old+'</b>. Selecione o complemento.':'Todas as posições completadas.')+'</p></div><div class="pair-choices">'+Object.entries(D.bases).map(([l,b])=>{actions.push({label:l+' · '+b.name,cmd:'base:'+l});return '<button data-act="base:'+l+'" class="'+(r.selected===l?'selected':'')+'" style="--base:'+b.hex+'">'+l+'</button>';}).join('')+'</div><div class="button-row">'+btn('Adicionar à fita','rep:place','primary',!r.selected)+btn('Pista','rep:hint')+'</div><p class="fine">'+r.answers.flat().filter(Boolean).length+' de '+r.sequence.length*2+' nucleotídeos adicionados.</p>';setInstruction('Cada fita original serve como molde. Escolha o nucleotídeo complementar e adicione na extremidade em crescimento da nova fita.','replicacao-construcao');}
 if(r.phase>=3){h+='<p>Selecione a fita original em cada molécula. A cor do esqueleto indica sua origem; as cores das bases continuam A, T, C e G.</p><div class="button-row">'+btn('Original da molécula 1','rep:identify:0:0','',r.identified.includes(0))+btn('Original da molécula 2','rep:identify:1:1','',r.identified.includes(1))+'</div><p>'+r.identified.length+' de 2 fitas originais identificadas.</p>';if(r.phase===4)h+='<div class="info-card"><p>✓ Cada molécula tem uma fita original e uma nova: replicação semiconservativa.</p></div>';h+=btn('Recomeçar experimento','rep:reset','wide');setInstruction('Em cada molécula, identifique a fita que já existia. Cada uma conserva uma fita original e possui uma fita nova.','replicacao-resultado');}
