 if(kind==='rep'){const r=S.rep;if(op==='predict'){const ok=a==='0';r.prediction=Number(a);log('previsao','replicacao',{choice:Number(a),correct:ok});r.phase=1;render();fb(ok?'Boa previsão. Investigue agora como isso acontece.':'Vamos testar a previsão e acompanhar a origem de cada fita.','ok');return;}if(op==='open'||op==='close'){r.open=Math.max(0,Math.min(1,r.open+(op==='open'?.25:-.25)));render();return;}if(op==='build'){if(r.open<1)return;r.phase=2;repNext();render();return;}if(op==='place'){repPlace();return;}if(op==='at'){repPlace(Number(a),Number(b));return;}if(op==='hint'&&r.target){log('pista','replicacao');fb('Use a complementaridade e siga a seta 5′ → 3′ da nova fita. Não mova a fita original.','warning');return;}if(op==='identify'){const branch=Number(a),strand=Number(b),correct=strand===(branch?1:0);log('identificacao','replicacao',{branch,strand,correct});if(!correct){fb('Essa fita é nova. Procure o esqueleto dourado.','warning');return;}if(!r.identified.includes(branch))r.identified.push(branch);if(r.identified.length===2){r.phase=4;mark('replicacao');}render();fb(r.phase===4?'Cada molécula preservou uma fita original. Experimento concluído.':'Original identificada. Encontre a original na outra molécula.');return;}if(op==='reset'){S.rep=freshRep();render();return;}}
