 $('guideStart').onclick=()=>handle('guide:start');$('summaryBtn').onclick=showSummary;$('settingsBtn').onclick=()=>{$('level').value=S.level;$('settingsDialog').showModal();};$('closeSummary').onclick=()=>$('summaryDialog').close();$('sourcesBtn').onclick=()=>$('sourcesDialog').showModal();
 $('sourcesContent').innerHTML='<p class="fine">A aplicação foi ampliada a partir do DNA Imersivo enviado. Preserva as bases e o pareamento, com atividades adicionais e revisões científicas documentadas em FONTES.md.</p><ul class="resource-list">'+D.sources.map(([t,u])=>'<li><a href="'+u+'" target="_blank" rel="noopener noreferrer">'+esc(t)+'</a></li>').join('')+'</ul><p class="fine">Modelo didático: cores e encaixes convencionais, escalas alteradas entre níveis e replicação conceitual de um trecho. Não simula cinética molecular, uma forquilha completa ou expressão gênica. A estrutura 1BNA é um exemplo separado. Revisão docente recomendada.</p><p class="fine">As conexões curriculares devem ser definidas pelo professor. Completar o pareamento não comprova, isoladamente, domínio de hereditariedade ou das leis de Mendel.</p>';
 $('level').onchange=e=>{S.level=e.target.value;renderSidebar();save();};$('voiceVolume').oninput=e=>{const n=Number(e.target.value);$('voiceValue').textContent=n+'%';narrator.setVoice(n/100);};$('musicVolume').oninput=e=>{const n=Number(e.target.value);$('musicValue').textContent=n+'%';narrator.setMusic($('musicEnabled').checked,n/100);};$('musicEnabled').onchange=e=>narrator.setMusic(e.target.checked);$('autoVoice').checked=S.autoVoice;$('autoVoice').onchange=e=>{S.autoVoice=e.target.checked;if(!S.autoVoice)narrator.stop();save();};$('syntheticVoice').onchange=e=>{narrator.synthetic=e.target.checked;narrator.stop();};$('captionsEnabled').checked=S.captions;$('captionsEnabled').onchange=e=>{S.captions=e.target.checked;$('captionText').hidden=!S.captions;save();};$('reducedMotion').checked=S.reducedMotion;$('reducedMotion').onchange=e=>{S.reducedMotion=e.target.checked;save();};$('quality').value=S.quality;$('quality').onchange=e=>{S.quality=e.target.value;if(view)view.pixel=0;save();};
 $('newStudent').onclick=()=>{if(!confirm('Iniciar um novo aluno? Exporte o resumo antes de limpar esta sessão.'))return;narrator.stop();S=initial();inspectKey=null;feedbackText='';$('settingsDialog').close();save();switchView('estrutura',false);};$('repeatVoice').onclick=()=>narrator.say(instruction,instructionKey);$('stopVoice').onclick=()=>narrator.stop();$('closeInspect').onclick=()=>handle('inspect:close');$('centerBtn').onclick=()=>handle('center');$('rotateBtn').onclick=()=>{handle('rotate');if(view&&view.xr)view.buildXRUI();};$('zoomIn').onclick=()=>view&&view.zoom(1);$('zoomOut').onclick=()=>view&&view.zoom(-1);$('vrBtn').onclick=()=>handle('vr');
 $('fullscreenBtn').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else if(document.documentElement.requestFullscreen)document.documentElement.requestFullscreen({navigationUI:'hide'}).catch(()=>fb('O navegador não autorizou tela cheia.','warning'));};
 $('downloadJSON').onclick=()=>download('DNA-resumo.json',JSON.stringify(report(),null,2),'application/json');$('downloadCSV').onclick=()=>{const r=report(),rows=[['evento','habilidade','correto','posicao','escolha','data'],...r.events.map(e=>[e.event,e.skill,e.correct??'',e.position??'',e.choice??'',e.at])];const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');download('DNA-atividades.csv',csv,'text/csv;charset=utf-8');};
 $('backPortal').onclick=e=>{e.preventDefault();handle('catalog');};window.addEventListener('pagehide',()=>{save();narrator.dispose();});document.addEventListener('visibilitychange',()=>{if(document.hidden){narrator.stop();narrator.music.pause();}});
 if(T&&M)view=new LabView();else{$('webglError').hidden=false;$('stage').classList.add('error');}
 switchView(S.view,false);$('rotateBtn').textContent=S.autoRotate?'Ⅱ Pausar':'▷ Girar';
 window.DNALab={version:D.version,get state(){return S;},command:handle,report,view,narrator,loadMolecular};
